const partInfo={upper:['Colector superior','#5fa99d','Recibe la mezcla agua-vapor y permite separar ambas fases. Se conecta con los tubos hervidores y descendentes.'],lower:['Colector inferior','#4d8396','Recibe el agua de los descendentes y la distribuye a los tubos hervidores. Según el diseño puede acumular lodos.'],risers:['Tubos hervidores','#cc8851','Conectan la zona inferior con el colector superior. El calor produce una mezcla agua-vapor que asciende.'],down:['Tubos descendentes','#518db9','Llevan agua del colector superior al inferior. La diferencia de densidad sostiene la circulación natural.'],furnace:['Horno / zona de combustión','#df7547','Recinto en el que se libera calor por combustión. Aquí se representa su volumen, sin paredes ni quemadores detallados.'],outlet:['Salida de vapor','#c5a65c','Conduce el vapor hacia el sistema consumidor o el sobrecalentador. Se representa la conexión; no el interior de una válvula.'],wall:['Pared y techo tubulares','#b9a577','En la tipo M, una pared y un techo de tubos delimitan el horno lateral y se conectan a colectores. Representación reducida a unas pocas líneas.']};
let yaw=-.58,pitch=.24,zoom=1,raf,drawn=[],canvas,ctx,W,H;
function renderWorkshop(){const t=types[model];app.innerHTML=`<div class="workshop-head"><div><div class="eyebrow">LABORATORIO INTERACTIVO · UNIDADES 2, 3 Y 5</div><h1>Entendé cada pieza.<br><em>Armá el sistema.</em></h1></div><span class="lab-badge">3D · EXPLORACIÓN + MONTAJE</span></div><div class="model-tabs" aria-label="Tipos de caldera">${Object.entries(types).map(([id,t])=>`<button data-model="${id}" class="${model===id?'active':''}">${t.name}</button>`).join('')}</div>${model==='catalog'?catalog():`<div class="model-intro"><div><h2>${t.name}</h2><p>${t.desc}</p></div><div class="segmented"><button id="explore" class="${mode==='explore'?'active':''}">Explorar</button><button id="assemble" class="${mode==='assemble'?'active':''}">Armar caldera</button></div></div><div class="lab-layout"><section class="viewport"><div class="viewport-top"><span class="tag">MODELO CONCEPTUAL</span><span id="counter">${mode==='assemble'?placed.size+' / '+partIds().length+' piezas':'CORTE ABIERTO'}</span></div><canvas id="model-canvas" tabindex="0" aria-label="Modelo 3D de caldera. Arrastrá para girar; usá las flechas del teclado para rotar y más o menos para zoom. Seleccioná las piezas en la lista lateral."></canvas><div class="canvas-help">Arrastrá para girar · Rueda para zoom · Tocá una pieza para identificarla</div><div class="viewport-tools"><button id="reset-view" class="secondary">↺ Vista inicial</button><button id="zoom-out" class="secondary" aria-label="Alejar">−</button><button id="zoom-in" class="secondary" aria-label="Acercar">+</button><button id="flow-toggle" class="secondary">${flow?'Ocultar':'Ver'} circulación</button></div><div class="explode-control"><label for="explode">Vista separada</label><input id="explode" type="range" min="0" max="100" value="${explode*100}" aria-label="Separación de las piezas"><span>Montada ↔ Despiece</span></div><div class="legend"><span><i style="background:#518db9"></i>Agua descendente</span><span><i style="background:#cc8851"></i>Mezcla ascendente</span><span><i style="background:#df7547"></i>Zona caliente</span></div></section><section class="parts-panel"><div class="eyebrow">${mode==='assemble'?'BANCO DE PIEZAS':'INSPECTOR DE COMPONENTES'}</div><p class="panel-help">${mode==='assemble'?'Elegí una pieza y tocá su ubicación en el modelo. Los contornos muestran los lugares disponibles.':'Seleccioná una pieza para ubicarla y entender con qué se conecta.'}</p><div id="parts-list"></div><div id="part-detail"></div><div class="feedback" id="feedback" role="status"></div>${mode==='assemble'?'<button id="restart" class="secondary">Reiniciar montaje</button>':''}</section></div><div class="source-bar"><strong>Lectura del modelo</strong><p>${t.source} Geometría esquemática, sin escala: se omiten accesorios y detalles constructivos. Los colores distinguen funciones, no materiales reales.</p><a href="${sources.book}" target="_blank" rel="noopener">Consultar Bobbio ↗</a></div><div class="study-strip"><div><h3>Ahora explicalo sin mirar.</h3><p>¿Por dónde baja el agua? ¿Dónde se forma la mezcla? ¿Qué recibe el colector superior?</p></div><a class="button" href="#oral">Practicar el oral →</a></div>`}`;document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>{model=b.dataset.model;placed.clear();selected='upper';explode=0;window.stopModel?.();renderWorkshop()});if(model==='catalog')return;canvas=document.querySelector('#model-canvas');ctx=canvas.getContext('2d');document.querySelector('#explore').onclick=()=>{mode='explore';render()};document.querySelector('#assemble').onclick=()=>{mode='assemble';placed.clear();render()};document.querySelector('#explode').oninput=e=>{explode=+e.target.value/100};document.querySelector('#reset-view').onclick=()=>{yaw=-.58;pitch=.24;zoom=1;explode=0;document.querySelector('#explode').value=0};document.querySelector('#zoom-in').onclick=()=>zoom=Math.min(1.8,zoom+.15);document.querySelector('#zoom-out').onclick=()=>zoom=Math.max(.5,zoom-.15);document.querySelector('#flow-toggle').onclick=()=>{flow=!flow;document.querySelector('#flow-toggle').textContent=(flow?'Ocultar':'Ver')+' circulación'};if(document.querySelector('#restart'))document.querySelector('#restart').onclick=()=>{placed.clear();updateParts();document.querySelector('#feedback').textContent='Montaje reiniciado. Elegí una pieza.'};updateParts();bindCanvas();raf=requestAnimationFrame(draw)}
function catalog(){return `<div class="page-top"><h2>Tipos encontrados en Bobbio</h2><p class="lead">Estas fichas organizan lo que sigue. Los modelos 3D disponibles son los de las pestañas anteriores.</p></div><div class="grid">${[['Tubos rectos','Capítulo 3 · desde p. 15','Cabezal y tubos rectos: otra disposición de caldera acuotubular.'],['ESD II · Foster Wheeler','Capítulo 6 · desde p. 39','Caldera con sobrecalentador externo.'],['MR y M12 · Babcock & Wilcox','Capítulo 7 · pp. 51–55','Diseños radiantes descritos en el libro.'],['V2M y V2M8 · Combustion Engineering','Capítulo 7 · pp. 55–61','Variantes con sobrecalentador vertical.'],['Circuitos UR y UB · Kawasaki','Capítulo 7 · pp. 61–69','Circuitos de alta eficiencia y recalentamiento.'],['¿Tipo W?','Pendiente de verificar','No se confirmó esta denominación en el índice consultado. No se presenta como tipo validado.']].map(([title,ref,text])=>`<article class="card"><span class="tag ${title.includes('W?')?'pending':''}">${title.includes('W?')?'POR CONFIRMAR':'REFERENCIA LOCALIZADA'}</span><h3>${title}</h3><p>${text}</p><p class="source">${ref}</p></article>`).join('')}</div><p class="source"><a href="${sources.book}" target="_blank" rel="noopener">Ver índice y capítulos en Bobbio ↗</a></p>`}
function partIds(){return ['upper','lower','risers','down','furnace','outlet',...(model==='M'?['wall']:[])]}
function updateParts(){document.querySelector('#parts-list').innerHTML=partIds().map(id=>`<button class="part-item ${id===selected?'selected':''}" data-part="${id}"><i style="background:${partInfo[id][1]}"></i><span>${partInfo[id][0]}</span><small>${mode==='assemble'?(placed.has(id)?'✓':'＋'):'↗'}</small></button>`).join('');document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{selected=b.dataset.part;updateParts();if(mode==='assemble')document.querySelector('#feedback').textContent=placed.has(selected)?'Esta pieza ya está colocada.':'Buscá su ubicación en el modelo y tocala.'});const p=partInfo[selected];document.querySelector('#part-detail').innerHTML=`<div class="detail-number">${String(partIds().indexOf(selected)+1).padStart(2,'0')} / ${String(partIds().length).padStart(2,'0')}</div><h3>${p[0]}</h3><p>${p[2]}</p>${mode==='assemble'&&!placed.has(selected)?'<button id="guided-place" class="secondary">Colocar con ayuda</button>':''}`;if(document.querySelector('#guided-place'))document.querySelector('#guided-place').onclick=()=>place(selected,true);document.querySelector('#counter').textContent=mode==='assemble'?placed.size+' / '+partIds().length+' piezas':'CORTE ABIERTO'}
function place(id,help=false){if(placed.has(id)){document.querySelector('#feedback').textContent='Esa pieza ya está instalada.';return}if(id!==selected){document.querySelector('#feedback').textContent='Ese lugar corresponde a '+partInfo[id][0].toLowerCase()+'. Probá otra ubicación.';return}placed.add(id);updateParts();document.querySelector('#feedback').textContent=placed.size===partIds().length?'✓ Montaje completo. Ahora explicá cómo circula el agua entre las piezas.':(help?'Pieza colocada con ayuda. ':'¡Ubicación correcta! ')+partInfo[id][0]+'.'}
const add=(a,b)=>a.map((x,i)=>x+b[i]),sub=(a,b)=>a.map((x,i)=>x-b[i]),mul=(a,n)=>a.map(x=>x*n),norm=a=>mul(a,1/Math.hypot(...a)),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
let faces=[];function cyl(a,b,r,id){const dir=norm(sub(b,a)),u=norm(cross(dir,Math.abs(dir[1])>.95?[1,0,0]:[0,1,0])),v=cross(dir,u),n=12;let A=[],B=[];for(let i=0;i<n;i++){const off=add(mul(u,r*Math.cos(i*2*Math.PI/n)),mul(v,r*Math.sin(i*2*Math.PI/n)));A.push(add(a,off));B.push(add(b,off))}for(let i=0;i<n;i++)faces.push({v:[A[i],A[(i+1)%n],B[(i+1)%n],B[i]],id,shade:.68+.3*Math.sin(i*2*Math.PI/n)});faces.push({v:A,id,shade:.9},{v:B,id,shade:.75})}
function box(center,size,id){const [x,y,z]=center,[a,b,c]=size.map(n=>n/2);const v=[[-a,-b,-c],[a,-b,-c],[a,b,-c],[-a,b,-c],[-a,-b,c],[a,-b,c],[a,b,c],[-a,b,c]].map(p=>add(p,[x,y,z]));[[0,1,2,3],[4,5,6,7],[0,1,5,4],[3,2,6,7],[1,2,6,5],[0,3,7,4]].forEach((f,i)=>faces.push({v:f.map(k=>v[k]),id,shade:.6+i*.06}))}
function geometry(){faces=[];const e=explode;const sx=model==='D'?-1.1:0;const upper=[sx,1.5+e*.9,0];cyl(add(upper,[0,0,-1.55]),add(upper,[0,0,1.55]),.34,'upper');const bottoms=model==='A'||model==='M'?[-1.3,1.3]:[sx];for(const x of bottoms)cyl([x,-1.5-e*.8,-1.4],[x,-1.5-e*.8,1.4],.25,'lower');for(let z=-1.2;z<=1.21;z+=.3){for(const x of bottoms){if(model==='D'){const pts=[[sx,1.35,z],[1.15+e*.9,1.1,z],[1.6+e*.9,.65,z],[1.6+e*.9,-1.1,z],[sx,-1.4,z]];for(let k=0;k<pts.length-1;k++)cyl(pts[k],pts[k+1],.055,'risers')}else cyl([sx+(x-sx)*.08+e*.35,1.25,z],[x+e*.35,-1.35,z],.055,'risers')}}for(const x of bottoms){const z=-1.6-e*.7;cyl([sx,1.4,z],[x,-1.4,z],.09,'down');cyl([sx,1.4,z],[sx,1.4,-1.35],.09,'down');cyl([x,-1.4,z],[x,-1.4,-1.2],.09,'down')}box([model==='D'?.45:model==='M'?-.7:0,-.1,0+e*1.5],[model==='D'?1.5:.65,1.7,2.2],'furnace');cyl([sx,1.75+e*.9,.6],[sx,2.3+e*1.7,.6],.1,'outlet');cyl([sx,2.3+e*1.7,.6],[sx+.65,2.3+e*1.7,.6],.1,'outlet');if(model==='M'){for(let z=-1;z<=1.01;z+=.35){cyl([-2.35-e*.6,-1.4,z],[-2.35-e*.6,1,z],.06,'wall');cyl([-2.35-e*.6,1,z],[0,1.4,z],.06,'wall')}cyl([-2.35-e*.6,-1.4,-1.3],[-2.35-e*.6,-1.4,1.3],.12,'wall')}}
function project(p){const x=p[0]*Math.cos(yaw)+p[2]*Math.sin(yaw),z=-p[0]*Math.sin(yaw)+p[2]*Math.cos(yaw);const y=p[1]*Math.cos(pitch)-z*Math.sin(pitch),d=p[1]*Math.sin(pitch)+z*Math.cos(pitch);const scale=Math.min(W/7.6,H/6.6)*zoom*7/(7+d);return [W/2+x*scale,H*.51-y*scale,d]}
function shade(hex,n){const c=hex.match(/\w\w/g).map(x=>Math.round(parseInt(x,16)*n));return `rgb(${c.join(',')})`}
function draw(time){if(!canvas?.isConnected)return;const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;if(canvas.width!==Math.round(W*dpr)||canvas.height!==Math.round(H*dpr)){canvas.width=W*dpr;canvas.height=H*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.strokeStyle='#dce7e0';ctx.lineWidth=.7;for(let n=-4;n<=4;n++){const a=project([n,-2, -4]),b=project([n,-2,4]),c=project([-4,-2,n]),d=project([4,-2,n]);ctx.beginPath();ctx.moveTo(...a.slice(0,2));ctx.lineTo(...b.slice(0,2));ctx.moveTo(...c.slice(0,2));ctx.lineTo(...d.slice(0,2));ctx.stroke()}geometry();drawn=faces.map(f=>({...f,p:f.v.map(project)})).map(f=>({...f,depth:f.p.reduce((s,p)=>s+p[2],0)/f.p.length})).sort((a,b)=>b.depth-a.depth);for(const f of drawn){const ghost=mode==='assemble'&&!placed.has(f.id),hot=f.id===selected;ctx.beginPath();f.p.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.globalAlpha=ghost?.11:f.id==='furnace'?.2:1;ctx.fillStyle=shade(partInfo[f.id][1],hot?Math.min(1.15,f.shade+.18):f.shade);ctx.fill();ctx.globalAlpha=ghost?.24:f.id==='furnace'?.4:.55;ctx.strokeStyle=hot?'#173e3d':shade(partInfo[f.id][1],.65);ctx.lineWidth=hot?1.2:.4;ctx.stroke()}ctx.globalAlpha=1;if(flow&&(mode==='explore'||placed.size===partIds().length)){const t=(time/2200)%1,sx=model==='D'?-1.1:0;for(let k=0;k<4;k++){const v=(t+k/4)%1;dot3([sx,1.4-v*2.8,-1.65-explode*.7],'#2f80c1');const bx=model==='A'||model==='M'?1.3:sx;if(model==='D'){const points=[[sx,-1.4,1.22],[1.6,-1.1,1.22],[1.6,.65,1.22],[1.15,1.1,1.22],[sx,1.35,1.22]],s=v*4,j=Math.min(3,Math.floor(s));dot3(add(points[j],mul(sub(points[j+1],points[j]),s-j)),'#eea64c')}else dot3([bx*(1-v),-1.35+v*2.7,1.22],'#eea64c')}}raf=requestAnimationFrame(draw)}
