function inside(p,vs){let hit=false;for(let i=0,j=vs.length-1;i<vs.length;j=i++){const a=vs[i],b=vs[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])hit=!hit}return hit}
function bindCanvas(){let last=null,start=null,moved=false;canvas.onpointerdown=e=>{last=[e.clientX,e.clientY];start=last;moved=false;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!last)return;if(Math.hypot(e.clientX-start[0],e.clientY-start[1])>5)moved=true;yaw+=(e.clientX-last[0])*.008;pitch=Math.max(-.7,Math.min(.9,pitch+(e.clientY-last[1])*.006));last=[e.clientX,e.clientY]};canvas.onpointerup=e=>{last=null;if(moved)return;const r=canvas.getBoundingClientRect(),p=[e.clientX-r.left,e.clientY-r.top];const hits=[...drawn].reverse().filter(f=>inside(p,f.p));const hit=hits.find(f=>f.id===selected)||hits.find(f=>f.id!=='furnace')||hits[0];if(!hit)return;if(mode==='assemble')place(hit.id);else{selected=hit.id;updateParts()}};canvas.onpointercancel=()=>last=null;canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.5,Math.min(1.8,zoom-e.deltaY*.001))};canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')yaw-=.12;if(e.key==='ArrowRight')yaw+=.12;if(e.key==='ArrowUp')pitch=Math.min(.9,pitch+.1);if(e.key==='ArrowDown')pitch=Math.max(-.7,pitch-.1);if(e.key==='+'||e.key==='=')zoom=Math.min(1.8,zoom+.1);if(e.key==='-')zoom=Math.max(.5,zoom-.1)}}}
window.stopModel=()=>cancelAnimationFrame(raf);render();
